begin;
create extension if not exists pgtap with schema extensions;
select no_plan();

select has_table('public', 'world_invites', 'historical invite metadata table remains');
select has_column('public', 'world_members', 'joined_via_invite_id', 'retry is tied to the current invitation membership');
select ok(has_function_privilege('authenticated', 'public.create_world_invite(uuid)', 'EXECUTE'), 'authenticated owner can call invite issuance');
select ok(not has_function_privilege('authenticated', 'public.join_world_by_member_code(text)', 'EXECUTE'), 'legacy reusable code cannot join');

-- Every fixture is transaction-local; generated codes never enter TAP output.
insert into auth.users(id) select ('00000000-0000-0000-0000-' || lpad(n::text,12,'0'))::uuid from generate_series(801,815) n;
insert into public.worlds(id,owner_id,name,timezone) values
('81000000-0000-0000-0000-000000000001','00000000-0000-0000-0000-000000000801','Invite','UTC'),
('81000000-0000-0000-0000-000000000002','00000000-0000-0000-0000-000000000804','Other','UTC');
create temporary table invite_fixture (invite_id uuid, code text, created_at timestamptz, expires_at timestamptz);
select set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000801',true);
insert into invite_fixture select * from public.create_world_invite('81000000-0000-0000-0000-000000000001');
select ok((select code ~ '^[0-9a-f]{64}$' from invite_fixture),'issued code has 256 random bits in hex');
select ok((select expires_at-created_at=interval '168 hours' from invite_fixture),'exact 168-hour expiry');
select ok((select i.code_hash <> f.code and i.code_hash=encode(extensions.digest(convert_to(f.code,'UTF8'),'sha256'),'hex') from public.world_invites i join invite_fixture f on f.invite_id=i.id),'only digest is persisted');
select ok((select to_jsonb(i) ? 'status' and not (to_jsonb(i) ?| array['code','code_hash','used_by']) from public.list_world_invites('81000000-0000-0000-0000-000000000001') i),'owner listing contains status and no secret or user identifier');
grant select on invite_fixture to authenticated;
set local role authenticated;
select throws_ok($$select * from public.world_invites$$,'42501',null,'no direct invite read');
select set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000802',true);
select throws_ok($$select * from public.create_world_invite('81000000-0000-0000-0000-000000000001')$$,'42501',null,'non-owner cannot issue');
select throws_ok($$select * from public.list_world_invites('81000000-0000-0000-0000-000000000001')$$,'42501',null,'non-owner cannot list');
select throws_ok($$select * from public.revoke_world_invite((select invite_id from invite_fixture))$$,'42501',null,'non-owner cannot revoke');
reset role;
select is((select status from public.accept_world_invite('  ' || upper((select code from invite_fixture)) || '  ')),'accepted','uppercase and edge spaces normalize');
select ok((select used_by='00000000-0000-0000-0000-000000000802' and used_at is not null from public.world_invites where id=(select invite_id from invite_fixture)),'consumption recorded with membership');
select ok((select joined_via_invite_id=(select invite_id from invite_fixture) from public.world_members where user_id='00000000-0000-0000-0000-000000000802'),'membership binds retry to this invite');
update public.world_invites set expires_at=clock_timestamp()-interval '1 second' where id=(select invite_id from invite_fixture);
select is((select status from public.accept_world_invite((select code from invite_fixture))),'already_accepted','same membership confirms retry after expiry');
select set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000803',true);
select is((select status from public.accept_world_invite((select code from invite_fixture))),'unavailable','another user cannot reuse consumed code');
select ok((select world_id is null from public.accept_world_invite('invalid')),'failure hides target world');
select set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000802',true);
select ok(public.leave_world('81000000-0000-0000-0000-000000000001'),'member can leave');
select is((select status from public.accept_world_invite((select code from invite_fixture))),'unavailable','leaving invalidates consumed-code retry');
truncate invite_fixture;
select set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000801',true);
insert into invite_fixture select * from public.create_world_invite('81000000-0000-0000-0000-000000000001');
select is((select status from public.revoke_world_invite((select invite_id from invite_fixture))),'revoked','owner revokes');
select is((select status from public.revoke_world_invite((select invite_id from invite_fixture))),'already_revoked','revoke is idempotent');
select set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000805',true);
select is((select status from public.accept_world_invite((select code from invite_fixture))),'unavailable','revoked code cannot join');
truncate invite_fixture;
select set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000801',true);
insert into invite_fixture select * from public.create_world_invite('81000000-0000-0000-0000-000000000001');
insert into public.world_members(world_id,user_id,role) values ('81000000-0000-0000-0000-000000000001','00000000-0000-0000-0000-000000000806','member');
select ok(public.transfer_world_owner('81000000-0000-0000-0000-000000000001','00000000-0000-0000-0000-000000000806'),'transfer succeeds');
select ok((select revoked_at is not null and used_at is null from public.world_invites where id=(select invite_id from invite_fixture)),'transfer permanently revokes pending invitation');
select set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000806',true);
select ok(public.transfer_world_owner('81000000-0000-0000-0000-000000000001','00000000-0000-0000-0000-000000000801'),'ownership can return');
select ok((select revoked_at is not null from public.world_invites where id=(select invite_id from invite_fixture)),'ownership return does not restore invitation');
select set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000807',true);
select is((select status from public.accept_world_invite(repeat('x',257))),'unavailable','oversized input rejected before hashing');
select is((select status from public.accept_world_invite('bad')),'unavailable','second failure');
select is((select status from public.accept_world_invite('bad')),'unavailable','third failure');
select is((select status from public.accept_world_invite('bad')),'unavailable','fourth failure');
select is((select status from public.accept_world_invite('bad')),'unavailable','fifth failure commits block');
select is((select status from public.accept_world_invite('bad')),'rate_limited','sixth attempt is blocked');
select ok((select failed_attempts=5 and blocked_until>clock_timestamp() from private.member_code_join_attempts where user_id='00000000-0000-0000-0000-000000000807'),'counter and block persist without exceptions');
select ok(not has_function_privilege('anon','public.accept_world_invite(text)','EXECUTE'),'anon cannot accept');
select ok(not has_function_privilege('anon','private.accept_world_invite(text)','EXECUTE'),'anon cannot call private helper');
select ok((select not prosecdef from pg_proc where oid='public.accept_world_invite(text)'::regprocedure),'public wrapper uses invoker');
truncate invite_fixture;
select set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000801',true);
insert into invite_fixture select * from public.create_world_invite('81000000-0000-0000-0000-000000000001');
select set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000804',true);
select is((select status from public.accept_world_invite((select code from invite_fixture))),'already_member','existing membership prevents consumption');
select ok((select used_at is null from public.world_invites where id=(select invite_id from invite_fixture)),'already member leaves invite active');
select ok((select failed_attempts=0 from private.member_code_join_attempts where user_id='00000000-0000-0000-0000-000000000804'),'already member is not a guess failure');
select set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000808',true);
savepoint accept_rollback;
select is((select status from public.accept_world_invite((select code from invite_fixture))),'accepted','accept inside rollback probe');
rollback to accept_rollback;
select ok(not exists(select 1 from public.world_members where user_id='00000000-0000-0000-0000-000000000808'),'rollback removes membership');
select ok((select used_at is null from public.world_invites where id=(select invite_id from invite_fixture)),'rollback removes consumption');
update public.world_invites set expires_at=clock_timestamp() where id=(select invite_id from invite_fixture);
select is((select status from public.accept_world_invite((select code from invite_fixture))),'unavailable','expiry boundary denies new membership');
update public.world_invites set expires_at=clock_timestamp()+interval '1 hour' where id=(select invite_id from invite_fixture);
insert into public.world_members(world_id,user_id,role) select '81000000-0000-0000-0000-000000000001'::uuid,('00000000-0000-0000-0000-'||lpad(n::text,12,'0'))::uuid,'member' from generate_series(809,815) n;
insert into public.world_members(world_id,user_id,role) values ('81000000-0000-0000-0000-000000000001','00000000-0000-0000-0000-000000000803','member');
select is((select status from public.accept_world_invite((select code from invite_fixture))),'world_full','full group denies without consumption');
select ok((select used_at is null from public.world_invites where id=(select invite_id from invite_fixture)),'full group leaves invite unconsumed');
select is((select count(*)::integer from public.world_members where world_id='81000000-0000-0000-0000-000000000001'),10,'capacity is preserved');
select * from finish();
rollback;
